// Pure: the Doros section of /etc/hosts. The root helper (helper/doros-block.sh, generated by
// helperScript.ts) does the same transform in awk; helperScript.test.ts runs it against these
// functions so the two can't drift apart. Everything outside the section stays byte-for-byte.

export const BLOCK_BEGIN = "# BEGIN DOROS BLOCK";
export const BLOCK_END = "# END DOROS BLOCK";

/** A BEGIN marker with no END after it: hand-edited, so don't guess what to remove. */
export class MalformedHostsError extends Error {
  constructor() {
    super(`hosts file has "${BLOCK_BEGIN}" without "${BLOCK_END}"; fix it by hand`);
    this.name = "MalformedHostsError";
  }
}

const LABEL = "(?!-)[a-z0-9-]{1,63}(?<!-)";
const DOMAIN_RE = new RegExp(`^${LABEL}(?:\\.${LABEL})+$`);

/** Plain lowercase hostname with at least two labels. Keeps anything odd out of a root-written file. */
export function isValidDomain(domain: string): boolean {
  return domain.length <= 253 && DOMAIN_RE.test(domain);
}

/** The section, with an IPv4 and an IPv6 entry per domain. Ends with a newline. */
export function blockSection(domains: readonly string[]): string {
  if (domains.length === 0) throw new Error("block list needs at least one domain");
  const bad = domains.find((d) => !isValidDomain(d));
  if (bad !== undefined) throw new Error(`invalid domain in block list: ${JSON.stringify(bad)}`);
  const entries = domains.flatMap((d) => [`0.0.0.0 ${d}`, `:: ${d}`]);
  return [BLOCK_BEGIN, ...entries, BLOCK_END].join("\n") + "\n";
}

/** Removes every Doros section. Other lines, blank lines, CRLFs and a missing final newline are kept. */
export function removeBlock(text: string): string {
  if (text === "") return text;
  const endsWithNewline = text.endsWith("\n");
  const lines = (endsWithNewline ? text.slice(0, -1) : text).split("\n");
  const kept: string[] = [];
  let inBlock = false;
  for (const line of lines) {
    if (inBlock) {
      if (line === BLOCK_END) inBlock = false;
    } else if (line === BLOCK_BEGIN) {
      inBlock = true;
    } else {
      kept.push(line);
    }
  }
  if (inBlock) throw new MalformedHostsError();
  if (kept.length === lines.length) return text;
  return kept.length === 0 ? "" : kept.join("\n") + (endsWithNewline ? "\n" : "");
}

/** Replaces any Doros section with a fresh one at the end of the file. */
export function addBlock(text: string, domains: readonly string[]): string {
  const section = blockSection(domains);
  const base = removeBlock(text);
  const separator = base === "" || base.endsWith("\n") ? "" : "\n";
  return base + separator + section;
}

export function hasBlock(text: string): boolean {
  return text.split("\n").some((line) => line === BLOCK_BEGIN);
}
